package net.civeira.phylax.features.access.tenantloginprovider.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class SamlIdpSsoUrlVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property saml idp sso url of tenant login provider ")
  void test_saml_idp_sso_url_v_o_builder() {
    Assertions.assertFalse(SamlIdpSsoUrlVO.nullValue().getSamlIdpSsoUrl().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(SamlIdpSsoUrlVO.tryFrom(null).getSamlIdpSsoUrl().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", SamlIdpSsoUrlVO.from("one").getSamlIdpSsoUrl().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> SamlIdpSsoUrlVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", SamlIdpSsoUrlVO.from("one").toString());
  }
}
